const body = $input.first().json.body || $input.first().json;
const payload = body.payload && body.payload.payment ? body.payload.payment.entity : body;
const amountPaise = Number(payload.amount || 0);
if (amountPaise !== 399900) {
  return [];
}
return [{
  json: {
    razorpay_payment_id: payload.id,
    workshop_date: (payload.notes && payload.notes.workshop_date) || new Date().toISOString().slice(0,10),
    amount_inr: 3999,
    paid_at: new Date((payload.created_at || Date.now()/1000) * 1000).toISOString(),
    parent_phone: payload.contact || null
  }
}];

